import json
import os
import re
import urllib.request

repo = os.environ['REPOSITORY']
token = os.environ['GH_TOKEN']
owner, name = repo.split('/')
bot = 'chatgpt-codex-connector[bot]'
receipt_markers = ('codex-review-receipt:v1', "Didn't find any major issues")
members = {'OWNER', 'MEMBER', 'COLLABORATOR'}

def call(url, data=None, method='GET'):
    body = json.dumps(data).encode() if data is not None else None
    request = urllib.request.Request(url, data=body, method=method, headers={
        'Authorization': f'Bearer {token}',
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
    })
    with urllib.request.urlopen(request, timeout=30) as response:
        return json.loads(response.read() or b'null')

def pages(path):
    items, page = [], 1
    while True:
        chunk = call(f'https://api.github.com/repos/{repo}/{path}{"&" if "?" in path else "?"}per_page=100&page={page}')
        items.extend(chunk)
        if len(chunk) < 100:
            return items
        page += 1

permission_cache = {}

def can_write(login):
    if login not in permission_cache:
        try:
            level = call(f'https://api.github.com/repos/{repo}/collaborators/{login}/permission').get('permission')
        except Exception as error:
            print(f'permission lookup for {login} failed: {error}')
            level = None
        permission_cache[login] = level in ('admin', 'maintain', 'write')
    return permission_cache[login]

def evaluate(number):
    pr = call(f'https://api.github.com/repos/{repo}/pulls/{number}')
    head = pr['head']['sha']
    if pr['state'] != 'open':
        print(f'PR #{number} is {pr["state"]}; nothing to publish.')
        return

    if any(label['name'] == 'heavy-tests' for label in pr.get('labels') or []):
        print(f'PR #{number} head={head} state=success (heavy-tests label: gate skipped)')
        call(f'https://api.github.com/repos/{repo}/statuses/{head}', {
            'state': 'success',
            'context': 'codex-review-gate',
            'description': 'Skipped: heavy-tests label (owner decision 2026-11-18)',
            'target_url': os.environ['RUN_URL'],
        }, method='POST')
        return

    commits = {c['sha'] for c in pages(f'pulls/{number}/commits')}
    reviews = pages(f'pulls/{number}/reviews')
    comments = pages(f'issues/{number}/comments')
    reactions = pages(f'issues/{number}/reactions')

    receipts = []
    for review in reviews:
        if review['user']['login'] == bot and any(m in (review.get('body') or '') for m in receipt_markers):
            receipts.append(f'review on {review["commit_id"][:12]}')
    if any(r['user']['login'] == bot and r['content'] == '+1' for r in reactions):
        receipts.append('connector thumbs-up')
    for comment in comments:
        body = comment.get('body') or ''
        if comment['user']['login'] == bot and any(m in body for m in receipt_markers):
            receipts.append('connector receipt comment')
            continue
        match = re.match(r'\s*Codex review\s*`?([0-9a-f]{7,40})`?', body)
        if match and (comment.get('author_association') in members or can_write(comment['user']['login'])):
            prefix = match.group(1)
            if any(sha.startswith(prefix) for sha in commits):
                receipts.append(f'local review of {prefix[:12]}')
        elif match:
            print(f'PR #{number}: ignored "Codex review" comment by {comment["user"]["login"]} ({comment.get("author_association")}, no write permission)')

    query = '''
    query($owner: String!, $name: String!, $number: Int!, $after: String) {
      repository(owner: $owner, name: $name) {
        pullRequest(number: $number) {
          reviewThreads(first: 100, after: $after) {
            pageInfo { hasNextPage endCursor }
            nodes {
              isResolved
              comments(first: 1) { nodes { author { login } body url } }
            }
          }
        }
      }
    }'''
    open_blocking, after = [], None
    while True:
        result = call('https://api.github.com/graphql', {
            'query': query,
            'variables': {'owner': owner, 'name': name, 'number': number, 'after': after},
        }, method='POST')
        if result.get('errors'):
            raise RuntimeError(f'GraphQL error: {result["errors"]}')
        threads = result['data']['repository']['pullRequest']['reviewThreads']
        for thread in threads['nodes']:
            first = (thread['comments']['nodes'] or [None])[0]
            if thread['isResolved'] or not first or not first.get('author'):
                continue
            login = first['author']['login']
            body = first.get('body') or ''
            if login in (bot, 'chatgpt-codex-connector') and re.search(r'\bP[01] Badge\b', body):
                open_blocking.append(first['url'])
        if not threads['pageInfo']['hasNextPage']:
            break
        after = threads['pageInfo']['endCursor']

    if open_blocking:
        state = 'failure'
        description = f'{len(open_blocking)} unresolved Codex P0/P1 thread(s)'
    elif receipts:
        state = 'success'
        description = f'Codex review receipt found ({len(receipts)})'
    else:
        state = 'pending'
        description = 'Waiting for a Codex review receipt on this PR'

    print(f'PR #{number} head={head} state={state} receipts={receipts} open_blocking={open_blocking}')
    call(f'https://api.github.com/repos/{repo}/statuses/{head}', {
        'state': state,
        'context': 'codex-review-gate',
        'description': description[:140],
        'target_url': os.environ['RUN_URL'],
    }, method='POST')

requested = os.environ.get('PR_NUMBER', '').strip()
if requested:
    numbers = [int(requested)]
else:
    numbers = [p['number'] for p in pages('pulls?state=open&base=main')]
failed = []
for number in numbers:
    try:
        evaluate(number)
    except Exception as error:  # one PR must not stop the sweep
        print(f'PR #{number}: {error}')
        failed.append(number)
if failed:
    raise SystemExit(f'evaluation failed for {failed}')
