import json
import os
import re
import subprocess
from pathlib import PurePosixPath

base = os.environ.get('BASE_SHA', '').strip().lower()
head = os.environ.get('HEAD_SHA', '').strip().lower()
result = {'rust': 'true', 'windows': 'true', 'surface': 'full'}

def valid_path(path: str) -> bool:
    return (
        bool(path)
        and '\x00' not in path
        and '\n' not in path
        and '\r' not in path
        and '\\' not in path
        and not path.startswith('/')
        and '..' not in path.split('/')
        and str(PurePosixPath(path)) == path
    )

try:
    if os.environ.get('BASE_QUALIFIED') != 'true':
        raise ValueError('unqualified protected base')
    if re.fullmatch(r'[0-9a-f]{40}', base) is None or re.fullmatch(r'[0-9a-f]{40}', head) is None:
        raise ValueError('invalid merge-group identity')
    if base == head:
        raise ValueError('empty merge-group identity')
    actual = subprocess.check_output(['git', 'rev-parse', 'HEAD'], text=True).strip().lower()
    if actual != base:
        raise ValueError('protected-base checkout mismatch')
    subprocess.check_call(['git', 'fetch', '--no-tags', '--depth=1', 'origin', head])
    fetched = subprocess.check_output(['git', 'rev-parse', head], text=True).strip().lower()
    if fetched != head:
        raise ValueError('merge-group head fetch mismatch')
    raw = subprocess.check_output([
        'git', 'diff', '--no-ext-diff', '--no-textconv', '--no-renames',
        '--name-status', '-z', base, head, '--'
    ])
    if not raw or not raw.endswith(b'\0'):
        raise ValueError('empty or incomplete merge-group diff')
    fields = raw[:-1].split(b'\0')
    if len(fields) % 2:
        raise ValueError('malformed merge-group diff')
    allowed_statuses = {b'A', b'M', b'D'}
    paths = []
    records = []
    for index in range(0, len(fields), 2):
        status = fields[index]
        if status not in allowed_statuses:
            raise ValueError('unmodelled merge-group status')
        path = fields[index + 1].decode('utf-8')
        if not valid_path(path):
            raise ValueError('invalid merge-group path')
        paths.append(path)
        records.append({
            'filename': path,
            'status': {b'A': 'added', b'M': 'modified', b'D': 'removed'}[status],
        })
        if status != b'D':
            row = subprocess.check_output(['git', 'ls-tree', head, '--', path], text=True).strip()
            parts = row.split(None, 3)
            if len(parts) != 4 or parts[0] not in {'100644', '100755'} or parts[1] != 'blob':
                raise ValueError('special candidate object mode')
    if not paths or len(set(paths)) != len(paths):
        raise ValueError('empty or duplicate merge-group paths')
    if all(path.startswith('docs/architecture/') and path.endswith('.md') for path in paths):
        result = {'rust': 'false', 'windows': 'false', 'surface': 'architecture-docs'}
except (OSError, UnicodeDecodeError, ValueError, subprocess.SubprocessError):
    result = {'rust': 'true', 'windows': 'true', 'surface': 'full'}
    paths = None
    records = None

# Physical server qualification uses the protected-base PR classifier and
# fails closed: anything but a proven unrelated candidate selects it.
server_qualification = 'true'
try:
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        'trusted_lanes', 'tools/repository/classify_pr_test_lanes.py'
    )
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    if isinstance(paths, list) and module.server_qualification_required(
        [{'filename': path} for path in paths], len(paths), True
    ) is False:
        server_qualification = 'false'
except Exception:
    server_qualification = 'true'

# Atlas source qualifications also use the protected-base classifier.
# Only an explicit false can deselect the bounded producer/consumer tests.
atlas_fullworld = 'true'
try:
    if isinstance(records, list) and module.atlas_fullworld_required(
        records, len(records), True
    ) is False:
        atlas_fullworld = 'false'
except Exception:
    atlas_fullworld = 'true'

# The World bundle gate uses the protected-base classifier too: only an
# explicit false (no compiler input in the complete candidate list) skips it.
world_bundle = 'true'
try:
    if isinstance(records, list) and module.world_bundle_required(
        records, len(records), True
    ) is False:
        world_bundle = 'false'
except Exception:
    world_bundle = 'true'

# Use protected-base exact-consumer routing and Cargo metadata for the
# exact synthetic candidate. Unconsumed auxiliary inputs skip both lanes;
# a proven server-only closure keeps Linux/PG and deselects Windows.
# Any other routing result or classifier/metadata failure stays FULL.
if result['surface'] == 'full' and isinstance(records, list) and records:
    try:
        metadata_path = os.path.join(os.environ['RUNNER_TEMP'], 'queue-metadata.json')
        with open(metadata_path, encoding='utf-8') as handle:
            metadata = json.load(handle)
