            and routed.get('reason') == 'server-only-exact-consumer-closure'
        ):
            result = {'rust': 'true', 'windows': 'false', 'surface': routed['surface']}
    except Exception:
        result = {'rust': 'true', 'windows': 'true', 'surface': 'full'}

with open(os.environ['GITHUB_OUTPUT'], 'a', encoding='utf-8') as output:
    output.write(f"postgres={result.get('postgres', result['rust'])}\n")
    output.write(f"rust={result['rust']}\n")
    output.write(f"windows={result['windows']}\n")
    output.write(f"surface={result['surface']}\n")
    output.write(f"server_qualification={server_qualification}\n")
    output.write(f"atlas_fullworld={atlas_fullworld}\n")
    output.write(f"world_bundle={world_bundle}\n")
print(f"Merge-group lane classification: {result} server_qualification={server_qualification}")
